import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents rounds half to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(2.6), 3);
  assert.equal(roundCents(-0.5), 0);
});

test('roundCents ignores binary noise', () => {
  assert.equal(roundCents(0.1 * 3 * 100), 30);
  assert.equal(roundCents(1.005 * 100), 100);
});

test('formatEuros adds the sign, thousands separators and two decimals', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(5), '€0.05');
  assert.equal(formatEuros(-250), '-€2.50');
  assert.equal(formatEuros(100000000), '€1,000,000.00');
});

test('parseEuros reads what people type', () => {
  assert.deepEqual(parseEuros('12'), { ok: true, value: 1200 });
  assert.deepEqual(parseEuros('12.5'), { ok: true, value: 1250 });
  assert.deepEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
  assert.deepEqual(parseEuros('12.345'), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
});

// Currency conversion tests
test('RATES has correct values', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR returns same amount', () => {
  const result = convert(10000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert EUR to USD', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  // 100 EUR = 100 * 1.085 = 108.5 USD = 10850 cents
  assert.equal(result.value, 10850);
});

test('convert EUR to GBP', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  // 100 EUR = 100 * 0.8425 = 84.25 GBP = 8425 cents
  assert.equal(result.value, 8425);
});

test('convert with rounding', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  // 0.01 EUR = 0.01 * 1.085 = 0.01085 USD ≈ 1.085 cents → 1 cent (rounded)
  assert.equal(result.value, 1);
});

test('convert with fractional cents rounds correctly', () => {
  const result = convert(1000, 'GBP');
  assert.equal(result.ok, true);
  // 10 EUR = 10 * 0.8425 = 8.425 GBP = 842.5 cents → 842 or 843 (banker's rounding)
  // 842.5 rounds to 842 (even)
  assert.equal(result.value, 842);
});

test('convert unknown currency returns error', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert handles large amounts', () => {
  const result = convert(1000000, 'USD');
  assert.equal(result.ok, true);
  // 10000 EUR = 10000 * 1.085 = 10850 USD = 1085000 cents
  assert.equal(result.value, 1085000);
});

test('convert handles zero', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert handles negative amounts', () => {
  const result = convert(-10000, 'USD');
  assert.equal(result.ok, true);
  // -100 EUR = -100 * 1.085 = -108.5 USD = -10850 cents
  assert.equal(result.value, -10850);
});

test('formatMoney formats EUR with € sign', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
  assert.equal(formatMoney(5, 'EUR'), '€0.05');
  assert.equal(formatMoney(100000000, 'EUR'), '€1,000,000.00');
});

test('formatMoney formats USD with $ sign', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
  assert.equal(formatMoney(5, 'USD'), '$0.05');
  assert.equal(formatMoney(100000000, 'USD'), '$1,000,000.00');
});

test('formatMoney formats GBP with £ sign', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
  assert.equal(formatMoney(5, 'GBP'), '£0.05');
  assert.equal(formatMoney(100000000, 'GBP'), '£1,000,000.00');
});

test('formatMoney handles negative amounts', () => {
  assert.equal(formatMoney(-250, 'EUR'), '-€2.50');
  assert.equal(formatMoney(-250, 'USD'), '-$2.50');
  assert.equal(formatMoney(-250, 'GBP'), '-£2.50');
});

test('formatMoney uses thousands separators', () => {
  assert.equal(formatMoney(1234567, 'USD'), '$12,345.67');
  assert.equal(formatMoney(1000000, 'GBP'), '£10,000.00');
});

test('formatMoney with small amounts', () => {
  assert.equal(formatMoney(1, 'USD'), '$0.01');
  assert.equal(formatMoney(99, 'EUR'), '€0.99');
  assert.equal(formatMoney(100, 'GBP'), '£1.00');
});

test('convert and formatMoney integration', () => {
  const eurCents = 10000;
  const usdResult = convert(eurCents, 'USD');
  const formatted = formatMoney(usdResult.value, 'USD');
  assert.equal(formatted, '$108.50');
});

test('convert and formatMoney for GBP', () => {
  const eurCents = 10000;
  const gbpResult = convert(eurCents, 'GBP');
  const formatted = formatMoney(gbpResult.value, 'GBP');
  assert.equal(formatted, '£84.25');
});

test('convert with different currencies from EUR', () => {
  const eurAmount = 42500;
  const usd = convert(eurAmount, 'USD');
  const gbp = convert(eurAmount, 'GBP');
  assert.equal(usd.ok, true);
  assert.equal(gbp.ok, true);
  assert.ok(usd.value > eurAmount);
  assert.ok(gbp.value < eurAmount);
});

test('formatMoney with zero', () => {
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('convert multiple times composes correctly', () => {
  // Convert EUR to USD, then manually back to EUR
  const eurCents = 10000;
  const usdCents = convert(eurCents, 'USD').value;
  const eurCents2 = Math.round(usdCents / RATES.USD);
  // Should be close to original (within rounding)
  assert.ok(Math.abs(eurCents2 - eurCents) <= 1);
});

test('convert preserves precision for common amounts', () => {
  const testAmounts = [100, 1000, 10000, 100000];
  for (const amount of testAmounts) {
    const usd = convert(amount, 'USD');
    assert.equal(usd.ok, true);
    assert.ok(Number.isInteger(usd.value));
  }
});

test('formatMoney with invoice total (48854 EUR cents)', () => {
  const eurCents = 48854;
  assert.equal(formatMoney(eurCents, 'EUR'), '€488.54');

  const usdCents = convert(eurCents, 'USD').value;
  assert.equal(formatMoney(usdCents, 'USD'), '$529.76');
});

test('convert case-sensitive currency codes', () => {
  const result = convert(10000, 'usd');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert with all supported currencies', () => {
  const amount = 10000;
  for (const currency of Object.keys(RATES)) {
    const result = convert(amount, currency);
    assert.equal(result.ok, true);
    assert.ok(Number.isInteger(result.value));
  }
});

